/// Background commands: spawn, poll the output, kill.
///
/// GENERATED by the split of `tools.zig`, then edited by hand. It lives in
/// its own file so it can be tested on its own, without the TUI.
const std = @import("std");
const common = @import("common.zig");
const bgproc = @import("../bgproc.zig");
const verify_mod = @import("../lib/verify.zig");

/// `bash_output`: the new output plus the status.
pub fn toolBashOutput(obj: std.json.ObjectMap, arena: std.mem.Allocator, reg: ?*bgproc.Registry) ![]const u8 {
    const r = reg orelse return error.NoBackgroundRegistry;
    const id_i = common.getInt(obj, "id") orelse return error.MissingId;
    if (id_i <= 0) return error.MissingId;
    const id: u32 = @intCast(id_i);

    var out = bgproc.Output{};
    const text = bgproc.read(r, &out, id) catch |err| switch (err) {
        // `NoNewOutput` is NOT reported as an error string: the model would read
        // it as "the command failed". It is the normal answer to "anything new?".
        error.NoNewOutput => return std.fmt.allocPrint(arena, "[job {d}] still running, nothing new yet", .{id}),
        error.UnknownJob => return std.fmt.allocPrint(arena,
            \\no job {d}. Start one with bash and run_in_background: true. (Jobs are
            \\also forgotten when zode restarts.)
            \\
        , .{id}),
    };

    // Tell it what to do next in the same breath, because the common failure is
    // the model polling three times in a row with nothing else happening.
    if (std.mem.eql(u8, bgproc.stateWord(r, id), "running")) {
        return std.fmt.allocPrint(arena, "{s}\n(do something else before polling again)", .{text});
    }
    return text;
}

/// `bash_kill`.
pub fn toolBashKill(
    obj: std.json.ObjectMap,
    arena: std.mem.Allocator,
    reg: ?*bgproc.Registry,
    io: std.Io,
) ![]const u8 {
    const r = reg orelse return error.NoBackgroundRegistry;
    const id_i = common.getInt(obj, "id") orelse return error.MissingId;
    if (id_i <= 0) return error.MissingId;
    const id: u32 = @intCast(id_i);
    if (bgproc.kill(r, io, id)) {
        return std.fmt.allocPrint(arena, "killed job {d}. You can still read what it printed with bash_output.", .{id});
    }
    return std.fmt.allocPrint(arena, "job {d} was not running ({s})", .{ id, bgproc.stateWord(r, id) });
}

// ── bash ─────────────────────────────────────────────────────
/// Runs a command in the FOREGROUND and collects its output, publishing the pid
/// so ESC can kill it.
///
/// This is `std.process.run` with one difference that matters: the child is
/// spawned HERE and its pid published, because `run` keeps the `Child` in its own
/// frame and returns only the output. Without the pid, ESC had nothing to kill and
/// a 30 s build ran to the end of its timeout while the UI said it had been
/// cancelled.
///
/// The timeout is applied on the READ (like `run` does) rather than by killing
/// the child: a command whose output pipe is full is stuck writing, not stuck
/// running, and reading with a timeout is the only way to notice that.
/// What a foreground command produced.
///
/// It is NOT `std.process.RunResult` because that type has no room for the one thing
/// that decides how the output may be presented: whether it is the whole thing.
pub const Foreground = struct {
    stdout: []u8,
    stderr: []u8,
    /// NULL when we stopped the command ourselves at the cap.
    ///
    /// It has to be optional because `Child.kill` REAPS: it waits for the process
    /// and clears the id, so the `wait` that would have told us the term cannot be
    /// called after it (`wait` asserts `id != null`, and without the assert it comes
    /// back as `error.Unexpected` from the vtable). Reporting a made-up exit code
    /// would be worse than reporting nothing: the model reads `exit=` as the
    /// command's own verdict, and `128+9` looks like a crash it caused.
    term: ?std.process.Child.Term,
    /// The output was longer than the cap, so the child was KILLED at the cap.
    truncated: bool = false,

    fn deinit(self: Foreground, gpa: std.mem.Allocator) void {
        gpa.free(self.stdout);
        gpa.free(self.stderr);
    }
};

/// What the model is told when a foreground command was cut short.
///
/// It says the command was STOPPED and not merely that the text is short, because
/// the child really is dead: a foreground command that kept running would block
/// forever on a pipe nobody is reading. "the output was truncated" alone reads as
/// "there was more and you could get it", and the model then retries the same thing.
pub const foreground_truncation_notice =
    "\\n… (output cut at the tool's cap and the command was stopped; re-run it " ++
    "through `head` or a narrower scope to get the rest)\\n";

/// Runs a command in the FOREGROUND and returns what it printed.
///
/// ## Why over the cap truncates instead of failing
///
/// This used to `return error.StreamTooLong` past the limit, with the reasoning that
/// "a tool result that stops mid-line looks to the model like the output ended". The
/// reasoning is sound and the consequence was not: `bash` is the tool the model
/// reaches for whenever a dedicated tool does not exist, and with a 16 KB cap
/// `cat`, `ls -laR`, `git log`, a `grep -r` through the shell and the output of
/// `zig build` were all DEAD — the model got an error instead of an answer, and no
/// amount of rephrasing the request gets under 16 KB.
///
/// The concern is real and it is answered the way `bgproc` already answers it for
/// background jobs: cut at the cap, say so in the text, and record it in a flag
/// (`truncated`) so the caller decides. The cap RESERVES the length of the notice, or
/// the notice is exactly what does not fit when it is needed most.
///
/// ## The child is killed, and that is not optional
///
/// Once we stop reading, a child that keeps writing blocks on a full pipe and
/// `wait()` never returns: the app hangs instead of returning a partial result.
pub fn runForeground(
    gpa: std.mem.Allocator,
    io: std.Io,
    command: []const u8,
    timeout_s: u64,
    out_limit: usize,
) !Foreground {
    var argv = [_][]const u8{ "/bin/sh", "-c", command };
    var child = try std.process.spawn(io, .{
        .argv = &argv,
        .stdin = .ignore,
        .stdout = .pipe,
        .stderr = .pipe,
        .pgid = 0,
    });
    // The `defer` is the normal exit's kill (the process is done by then). After a
    // truncation there is nothing left to kill: `child.kill` has already zeroed the
    // id, and killing a reaped pid is how you kill a stranger.
    defer child.kill(io);

    if (child.id) |pid| setForeground(pid);

    var mr_buffer: std.Io.File.MultiReader.Buffer(2) = undefined;
    var mr: std.Io.File.MultiReader = undefined;
    mr.init(gpa, io, mr_buffer.toStreams(), &.{ child.stdout.?, child.stderr.? });
    defer mr.deinit();

    const timeout: std.Io.Timeout = .{
        .duration = .{ .raw = .fromSeconds(@intCast(timeout_s)), .clock = .awake },
    };
    const stdout_reader = mr.reader(0);
    const stderr_reader = mr.reader(1);

    var truncated = false;
    while (mr.fill(4096, timeout)) |_| {
        if (stdout_reader.buffered().len > out_limit or
            stderr_reader.buffered().len > out_limit)
        {
            truncated = true;
            break;
        }
    } else |err| switch (err) {
        error.EndOfStream => {},
        error.Timeout => return error.Timeout,
        else => |e| return e,
    }

    var term: ?std.process.Child.Term = null;
    if (truncated) {
        // The group, not the pid: `/bin/sh -c "a && b"` has children, and killing only
        // the shell leaves the grandchild writing into the pipe nobody reads. This is
        // the same reasoning as `bgproc.killTree`.
        //
        // `kill` reaps, so there is no `wait` after it (see `Foreground.term`).
        if (child.id) |pid| std.posix.kill(-pid, std.posix.SIG.KILL) catch {};
        child.kill(io);
    } else {
        term = try child.wait(io);
    }
    clearForeground();

    const stdout_slice = try mr.toOwnedSlice(0);
    errdefer gpa.free(stdout_slice);
    const stderr_slice = try mr.toOwnedSlice(1);
    errdefer gpa.free(stderr_slice);

    return .{
        .stdout = stdout_slice,
        .stderr = stderr_slice,
        .term = term,
        .truncated = truncated,
    };
}

/// Foreground command in flight, for ESC to kill. Re-exported from `bgproc`
/// because that is where the pid lives (a `pid` and its process group are the same
/// subject) and this module is what spawns the command.
const setForeground = bgproc.setForeground;

const clearForeground = bgproc.clearForeground;

pub fn setAutoBackground(v: bool) void {
    auto_background = v;
}

/// The rule that makes this foreground `bash` a background job anyway, or null
/// to run it in the foreground.
///
/// Split out of `toolBash` because that one needs an `Io` and a live registry and
/// this is the whole DECISION, which is what has to be tested.
pub fn autoBackgroundRule(obj: std.json.ObjectMap, command: []const u8) ?[]const u8 {
    if (common.getBool(obj, "run_in_background")) return null;
    if (!auto_background) return null;
    // An explicit `timeout_seconds` means the model decided what it wanted from
    // this command. Overriding that would be overriding a decision, not a
    // default.
    if (common.getInt(obj, "timeout_seconds") != null) return null;
    const v = verify_mod.classify(command);
    if (v.kind != .slow_verify) return null;
    return v.matched;
}

/// Whether a known-slow verification is moved to background on its own.
///
/// A var, not a const, because `setAutoBackground` flips it at startup from the
/// environment: `ZODE_AUTO_BG=0` turns it off for someone who would rather watch
/// a build than have it disappear into a job.
pub var auto_background: bool = true;
